import{_ as e,c as r,o as t,ag as h}from"./chunks/framework.DnwzncJk.js";const _=JSON.parse('{"title":"炒股养家","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"src/wealth/炒股养家认识.md","filePath":"src/wealth/炒股养家认识.md","lastUpdated":1789898772000}'),l={name:"src/wealth/炒股养家认识.md"};function i(o,a,n,d,b,s){return t(),r("div",null,a[0]||(a[0]=[h('<h1 id="炒股养家" tabindex="-1">炒股养家 <a class="header-anchor" href="#炒股养家" aria-label="Permalink to &quot;炒股养家&quot;">​</a></h1><h2 id="人物简介" tabindex="-1">人物简介 <a class="header-anchor" href="#人物简介" aria-label="Permalink to &quot;人物简介&quot;">​</a></h2><p><strong>姓名</strong>：林广昌<br><strong>出生年</strong>：1977年<br><strong>出生地</strong>：上海<br><strong>学历</strong>：不详<br><strong>原职业</strong>：国企员工<br><strong>入市时间</strong>：90年代末<br><strong>资金</strong>：保守估计数十亿</p><hr><p>炒股养家，上海人，70后，A股当代知名游资的代表人物。他所创造的心法指引了无数股民的成功，被很多人视为当今游资第一人，并尊其为“养家老师”。</p><p>早在2015年大牛市中，他的资金量便已经突破10亿量级。</p><p>90年代末入市，经历了从短线到价值投资再到短线的过程，2008年正式辞职并开始职业炒股投资。初期的炒股投资之路并不顺利，当时他下定决心辞职开始炒股，却不料刚好赶上了当时的熊市。资金从最初的90多万亏损到最低40万元不到。面对自己十余年投资毫无结果，面对房贷、车子油钱、小孩奶粉钱等各种生活开销，所带来的迷茫和所承受的压力是常人难以体会。2008年是他人生中最低谷的一年。之后他沉寂了一年之久，开始思考，将主要精力都用在学习上，精心凝练自己的交易系统。当时职业炒手、Asking等大佬的成功事迹激励了他，他将他们奉为自己学习的榜样，以及要实现的人生目标。开始潜心研究他们的心法与技术，学习对于短线操作的信念。功夫不负有心人，后来逐渐悟道，理解了股市涨跌的真正原因。到了2010年5月的时候，资金比2008年熊市时翻了五倍，达到了200万元。之后一路高歌猛进，9月突破300万，11月突破400万，2011年1月资金突破600万，资金曲线平滑上升，一路向上，终成一方游资。</p><p>随后他开始分享一些自己的东西，不同于其他人在淘县留下的大都是关于短线技术的讨论，炒股养家多数分享的是在道的层面上的心法，最终形成了“养家心法”。“养家心法”写出了股市短线博弈的真谛。虽然只有寥寥数语，但真传一句话，假传万卷书，每每阅读都有一番新的感悟。</p><p>后来炒股养家逐渐淡出人们的视线，功成身隐。在2015年大牛市中，他的专用席位频繁出现在龙虎榜交易数据中，有人统计过他的交易金额，计算出他的资金体量至少在10亿元以上。</p><hr><h1 id="养家心法" tabindex="-1">养家心法 <a class="header-anchor" href="#养家心法" aria-label="Permalink to &quot;养家心法&quot;">​</a></h1><h2 id="_1-养家心法的核心思想" tabindex="-1">1. 养家心法的核心思想 <a class="header-anchor" href="#_1-养家心法的核心思想" aria-label="Permalink to &quot;1. 养家心法的核心思想&quot;">​</a></h2><p>核心思想是基于对市场情绪的揣摩，进而判断风险和收益的比较，并指导实际操作，故名曰心法。</p><h2 id="_2-股票走势的本质" tabindex="-1">2. 股票走势的本质 <a class="header-anchor" href="#_2-股票走势的本质" aria-label="Permalink to &quot;2. 股票走势的本质&quot;">​</a></h2><p>股票走势本质是由持币者与持筹者的博弈产生，应该多揣摩两者之心，让自己站在主动的这一方即可。</p><h2 id="_3-短线交易的本质" tabindex="-1">3. 短线交易的本质 <a class="header-anchor" href="#_3-短线交易的本质" aria-label="Permalink to &quot;3. 短线交易的本质&quot;">​</a></h2><p>交易的本质是群体博弈，追根溯源的话，就是随时衡量，场外的潜在买入者的钱的数量和买入倾向，与场内筹码的数量和卖出倾向，当前者大于后者就买入，当后者大于前者就卖出。</p><h2 id="_4-短线操作的核心思路和框架" tabindex="-1">4. 短线操作的核心思路和框架 <a class="header-anchor" href="#_4-短线操作的核心思路和框架" aria-label="Permalink to &quot;4. 短线操作的核心思路和框架&quot;">​</a></h2><p>交易的本质是群体博弈，追根溯源的话，就是随时衡量场外的潜在买入者的钱的数量和买入倾向，与场内筹码的数量和卖出倾向，当前者大于后者就买入，当后者大于前者就卖出。买入倾向的推理，大多来自赚钱效应，卖出倾向的推理，大多来自亏钱效应。然后再结合大盘，主流热点这些，进行瞬间的操作判断，操作是瞬间的，判断是动态的。</p><h2 id="_5-持筹者在分时下跌过程中如何操作" tabindex="-1">5. 持筹者在分时下跌过程中如何操作 <a class="header-anchor" href="#_5-持筹者在分时下跌过程中如何操作" aria-label="Permalink to &quot;5. 持筹者在分时下跌过程中如何操作&quot;">​</a></h2><p>让自己处于主动的一方，持筹者在下跌过程中想想同样和你持筹的人怎么想，如果他们想着给个反弹我就走，那你最好尽快走，如果他们想着让我解套我就走，那你就在他们解套之前走。再想想持币的人的想法，如果下跌会不会买，如果反弹会不会买。</p><h2 id="_6-股市短线情绪的酝酿有什么规律" tabindex="-1">6. 股市短线情绪的酝酿有什么规律 <a class="header-anchor" href="#_6-股市短线情绪的酝酿有什么规律" aria-label="Permalink to &quot;6. 股市短线情绪的酝酿有什么规律&quot;">​</a></h2><p>（1）情绪周期从酝酿到逐步展开有个逐步蔓延的过程，场内筹码的情绪部分从下跌空间有限转向失望离场。<br> （2）不过这个过程同时也是场外资金逐步累积的一个过程，当市场情绪逆转那一刻来临的时候，资金又会蜂拥而入，如此不断往复。<br> （3）如果说股市有什么规律的话，这种情绪转变的过程就是规律，而且可以预期的一千年内，这种规律亦不会有大的改变。</p><h2 id="_7-如何判断市场即将要崩溃" tabindex="-1">7. 如何判断市场即将要崩溃 <a class="header-anchor" href="#_7-如何判断市场即将要崩溃" aria-label="Permalink to &quot;7. 如何判断市场即将要崩溃&quot;">​</a></h2><p>（1）领跌品种中，部分是近期强势股，这会在一定程度上打击后市追涨的热情，同时也说明赚钱效应有一定程度降低。<br> （2）喜欢抄底的资金陷入被套局面，而抄底的人也亏钱的话，继续抄底的就会减少，这种状况就可能引发崩溃。<br> （3）这种盘面现象表示后市有一定崩盘的概率，不过这本身也是一个动态的判断过程，只是当下先空仓或低仓位回避这种概率，会使自己操作上更为主动。</p><h2 id="_8-如何找到大牛股" tabindex="-1">8. 如何找到大牛股 <a class="header-anchor" href="#_8-如何找到大牛股" aria-label="Permalink to &quot;8. 如何找到大牛股&quot;">​</a></h2><p>得散户心者得天下：人气所向，牛股所在。</p><h2 id="_9-如何操作龙头股票" tabindex="-1">9. 如何操作龙头股票 <a class="header-anchor" href="#_9-如何操作龙头股票" aria-label="Permalink to &quot;9. 如何操作龙头股票&quot;">​</a></h2><p>高手买入龙头，超级高手卖出龙头。</p><h2 id="_10-如何看待市场中人性的贪婪和恐慌" tabindex="-1">10. 如何看待市场中人性的贪婪和恐慌 <a class="header-anchor" href="#_10-如何看待市场中人性的贪婪和恐慌" aria-label="Permalink to &quot;10. 如何看待市场中人性的贪婪和恐慌&quot;">​</a></h2><p>别人贪婪时我更贪婪，别人恐慌时我更恐慌。</p><h2 id="_11-大盘顶部和底部时如何控制仓位" tabindex="-1">11. 大盘顶部和底部时如何控制仓位 <a class="header-anchor" href="#_11-大盘顶部和底部时如何控制仓位" aria-label="Permalink to &quot;11. 大盘顶部和底部时如何控制仓位&quot;">​</a></h2><p>敢于大盘低位空仓，敢于大盘高位满仓；心中无顶底，操作自随心。</p><h2 id="_12-如何看待止盈与止损" tabindex="-1">12. 如何看待止盈与止损 <a class="header-anchor" href="#_12-如何看待止盈与止损" aria-label="Permalink to &quot;12. 如何看待止盈与止损&quot;">​</a></h2><p>永不止损，永不止盈。只有进场，出局。买入机会，卖出不确定。出局就是出局，管它是止损还是止盈。<br> 炒股应有大局观，站在更高的角度来审视市场，选择机会大于风险的股票进行操作，而不是拘泥于止损止盈这类。本人是反对止盈和止损这类的说法的，看好买入，不看好卖出或者换股，操作越简单越好。</p><h2 id="_13-什么是大局观" tabindex="-1">13. 什么是大局观 <a class="header-anchor" href="#_13-什么是大局观" aria-label="Permalink to &quot;13. 什么是大局观&quot;">​</a></h2><p>（1）大局观就是政策面、技术面、资金面、基本面的综合，相辅相成。<br> （2）完善自己的系统，输赢交给概率，看不准的时候割肉就可以了，不必拘泥。</p><h2 id="_14-如何看清大局观" tabindex="-1">14. 如何看清大局观 <a class="header-anchor" href="#_14-如何看清大局观" aria-label="Permalink to &quot;14. 如何看清大局观&quot;">​</a></h2><p>（1）对于新手而言，没有捷径，只有经历过才能理解，至少完整的经历过一轮牛熊，最好两轮或以上，然后自行归纳总结。<br> （2）对于个股，不应拘泥于自己手中所持品种，而应最大限度的观察各板块走势，要对各个周期的领涨和领跌品种进行重点关注。<br> （3）对于操作，不要一味的追求个别技术指标，或者短期的所谓资金流进流出，主力庄家这些。<br> （4）对于大盘，不要过多依赖于预测什么点数顶底这些，而应多关注哪些在涨，哪些在跌，那些先前涨的或者跌的后来又怎么走了。<br> （5）大局观是一种感觉，或许有时候不明白，但是尽量多尝试让自己站在更高的高度来看待整个市场，一旦明白了，将受益无穷。</p><h2 id="_15-如何提升对市场预判的准确性" tabindex="-1">15. 如何提升对市场预判的准确性 <a class="header-anchor" href="#_15-如何提升对市场预判的准确性" aria-label="Permalink to &quot;15. 如何提升对市场预判的准确性&quot;">​</a></h2><p>以史为鉴，可知兴替。股票也一样，熟悉了以往热点轮动的规律后，自然预判的准确性就会提高。</p><h2 id="_16-如何能有好的心态" tabindex="-1">16. 如何能有好的心态 <a class="header-anchor" href="#_16-如何能有好的心态" aria-label="Permalink to &quot;16. 如何能有好的心态&quot;">​</a></h2><p>股票做好了，能实现稳定盈利，心态也就不是问题了。</p><h2 id="_17-热点的介入方式有哪些" tabindex="-1">17. 热点的介入方式有哪些 <a class="header-anchor" href="#_17-热点的介入方式有哪些" aria-label="Permalink to &quot;17. 热点的介入方式有哪些&quot;">​</a></h2><p>热点的介入，一种是提前预判埋伏，一种是盘中追击，随机应变为主。仓位，让自己觉得舒服就可以。</p><h2 id="_18-强势阶段和弱势阶段分别如何操作" tabindex="-1">18. 强势阶段和弱势阶段分别如何操作 <a class="header-anchor" href="#_18-强势阶段和弱势阶段分别如何操作" aria-label="Permalink to &quot;18. 强势阶段和弱势阶段分别如何操作&quot;">​</a></h2><p>根据不同阶段有所不同，如是强势阶段，就做龙头个股的主升浪，可以多拿几天；如是弱势阶段，可以学炒手的超跌反弹方法，做反弹为主，大盘超跌的时候买超跌的股票，大部分第二天冲高就走，不要有太多想法，如果情况出现不利，亏钱也走，如是平衡格局，就部分持有热点板块观察变盘方向，试错，加仓，向上买，争取顺势而为。</p><h2 id="_19-如何做超跌股的反弹" tabindex="-1">19. 如何做超跌股的反弹 <a class="header-anchor" href="#_19-如何做超跌股的反弹" aria-label="Permalink to &quot;19. 如何做超跌股的反弹&quot;">​</a></h2><p>根据市场的赚钱效应和恐慌效应来判断大势。有赚钱效应的情况下，做热点为主；有恐慌效应的情况下，做超跌为主。关于超跌度的把握：大盘的角度，连续下跌一段后，再出现大阴线，指数远离5日线；板块的角度，超跌的板块在连续下跌一段后，再次出现集体性的大幅杀跌；当两者结合的时候，便是超跌的出击时刻。</p><h2 id="_20-市场成交量极其低迷的时候应该如何操作" tabindex="-1">20. 市场成交量极其低迷的时候应该如何操作 <a class="header-anchor" href="#_20-市场成交量极其低迷的时候应该如何操作" aria-label="Permalink to &quot;20. 市场成交量极其低迷的时候应该如何操作&quot;">​</a></h2><p>低成交量不支持蓝筹行情，但是可以制造局部热点，是不是一日游，就看是什么样的局。</p><h2 id="_21-如何看待外围市场对a股的影响" tabindex="-1">21. 如何看待外围市场对A股的影响 <a class="header-anchor" href="#_21-如何看待外围市场对a股的影响" aria-label="Permalink to &quot;21. 如何看待外围市场对A股的影响&quot;">​</a></h2><p>外围通常只影响开盘，因此部分情况下可以利用外围股市做反向操作。</p><h2 id="_22-如何看待强势股票补跌" tabindex="-1">22. 如何看待强势股票补跌 <a class="header-anchor" href="#_22-如何看待强势股票补跌" aria-label="Permalink to &quot;22. 如何看待强势股票补跌&quot;">​</a></h2><p>超跌的品种稳住了，强势的个股机会就大些，超跌的品种继续创新低，强势的个股补跌在即。</p><h2 id="_23-如何很好的控制自己的资金市值曲线稳步上升" tabindex="-1">23. 如何很好的控制自己的资金市值曲线稳步上升 <a class="header-anchor" href="#_23-如何很好的控制自己的资金市值曲线稳步上升" aria-label="Permalink to &quot;23. 如何很好的控制自己的资金市值曲线稳步上升&quot;">​</a></h2><p>（1）我追求不断稳定的盈利，不确定时，采取偏保守的策略，尽量规避大的回撤，所以平时以小阴小阳为主。<br> （2）偶尔出现确定性较高的机会时，也会奋力出击，博取大阳。<br> （3）操作模式决定市值曲线，让自己觉得舒服就好。<br> 个人而言，喜欢的模式是重点把握好的机会，轻仓试验普通的机会，规避大盘下跌的风险，从这个角度，整体收益率的曲线应该是稳步向上的。</p><h2 id="_24-最开始的时候-您是怎么从低谷中走出来的" tabindex="-1">24. 最开始的时候，您是怎么从低谷中走出来的 <a class="header-anchor" href="#_24-最开始的时候-您是怎么从低谷中走出来的" aria-label="Permalink to &quot;24. 最开始的时候，您是怎么从低谷中走出来的&quot;">​</a></h2><p>历经了迷茫与痛苦，背负着生活的压力，是信念让我走到了今天，所以我非常看重这两个字。怀着坦诚和感恩的心，用科学的方法不断地研究，你的机会就会比别人多。技巧性的东西，Asking和炒手基本都说了，我能反复强调的就是信念。</p><h2 id="_25-用了多久实现稳定盈利" tabindex="-1">25. 用了多久实现稳定盈利 <a class="header-anchor" href="#_25-用了多久实现稳定盈利" aria-label="Permalink to &quot;25. 用了多久实现稳定盈利&quot;">​</a></h2><p>炒股也有十几年了，相对稳定盈利也就是这一年多。（这里指2010年）</p><h2 id="_26-您为什么专注于做短线" tabindex="-1">26. 您为什么专注于做短线 <a class="header-anchor" href="#_26-您为什么专注于做短线" aria-label="Permalink to &quot;26. 您为什么专注于做短线&quot;">​</a></h2><p>最早是做短线的，后来又搞价值投资，后来又搞回短线，不是反对其他方法，只是目前我们的市场比较适合短线。</p><h2 id="_27-辞职后职业炒股的成功概率有多高" tabindex="-1">27. 辞职后职业炒股的成功概率有多高 <a class="header-anchor" href="#_27-辞职后职业炒股的成功概率有多高" aria-label="Permalink to &quot;27. 辞职后职业炒股的成功概率有多高&quot;">​</a></h2><p>我觉得现在的职业炒股，好比80年代的下海，当时很多人对于下海也不置可否，结果很多人成为万元户，当然也可能被淹死，能不能成功，是很多因素共同构成的。现在的职业炒股，同样面临这样的问题，肯定会有很多人成就千万、亿万身家，当然也可能失败，能不能成功，也是诸多因素。就个人而言，当时决定辞职也是有较大风险的，因为以现在的角度看，好比跳下水的时候还没有学好游泳，但是在呛水的过程中，通过不断的学习，也学会了一些适合自己的方法。这是一场赌博，没有人能告诉你是不是一定会成功，就看你自己觉得是不是值得。</p><h2 id="_28-什么时候可以成为职业股民" tabindex="-1">28. 什么时候可以成为职业股民 <a class="header-anchor" href="#_28-什么时候可以成为职业股民" aria-label="Permalink to &quot;28. 什么时候可以成为职业股民&quot;">​</a></h2><p>资金方面，如果股市的收入能够超过开销即可；收益率方面，至少跑赢最优秀的公募基金和大多数私募基金；志向一定要远大，操作务必要稳健。</p><h2 id="_29-职业炒股初期是怎么过来的" tabindex="-1">29. 职业炒股初期是怎么过来的 <a class="header-anchor" href="#_29-职业炒股初期是怎么过来的" aria-label="Permalink to &quot;29. 职业炒股初期是怎么过来的&quot;">​</a></h2><p>在辞掉工作以后，又面临08年的大熊市，上有老下有小，股市资金不断缩水，同时还要从股市中不断提出生活费，心理上背负着压力时信念受到过挑战，说服自己继续坚持信念的正是Asking、炒手等榜样的力量，但是我挺过来了，所以我也希望自己能给同样经历着的人信念。</p><h2 id="_30-无法判断市场好坏的时候怎么办" tabindex="-1">30. 无法判断市场好坏的时候怎么办 <a class="header-anchor" href="#_30-无法判断市场好坏的时候怎么办" aria-label="Permalink to &quot;30. 无法判断市场好坏的时候怎么办&quot;">​</a></h2><p>我的操作里面含有很多的试错单，这些单子的结果大多是小赢小亏，到底是赚是亏不重要，重要的是在于我能借此感受到市场的情绪，从而判断收益和风险，以决定是否奋力一击，那才是关键。就好比拳击的时候很多的刺拳是为了试探对手，这些刺拳有没有打中不重要，重要的是借这个试探判断何时该出重拳，那才是关键。至于大盘是如何看的，个人而言是反对预测的，即便心中有预测也是为了应变做准备。</p><h2 id="_31-如何单纯看待技术手法" tabindex="-1">31. 如何单纯看待技术手法 <a class="header-anchor" href="#_31-如何单纯看待技术手法" aria-label="Permalink to &quot;31. 如何单纯看待技术手法&quot;">​</a></h2><p>追求技术的量化，曾经让我大量的时间钻这个牛角尖，还是有太多的人执迷于此，炒股若是这样可行的话，那些基金经理们应该比炒手们更有优势了。市场理解力和技术手法，一个内功一个外功，没有内功，强练外功，容易走火入魔。</p><h2 id="_32-如何控制仓位" tabindex="-1">32. 如何控制仓位 <a class="header-anchor" href="#_32-如何控制仓位" aria-label="Permalink to &quot;32. 如何控制仓位&quot;">​</a></h2><p>关于仓位，有好机会就重点搞，没有好机会就拿着钱，耐心等待或者轻仓练盘感，总之让自己觉得舒服就可以了。</p><h2 id="_33-如何分析成交量与涨停板好坏的关系" tabindex="-1">33. 如何分析成交量与涨停板好坏的关系 <a class="header-anchor" href="#_33-如何分析成交量与涨停板好坏的关系" aria-label="Permalink to &quot;33. 如何分析成交量与涨停板好坏的关系&quot;">​</a></h2><p>（1）成交量，主要是看成交量的变化。<br> （2）追板，主要看市场环境、热点。<br> （3）成交量再结合价格的变化，揣摩场内和场外人心的变化。</p><h2 id="_34-如何看待连续涨停的股票" tabindex="-1">34. 如何看待连续涨停的股票 <a class="header-anchor" href="#_34-如何看待连续涨停的股票" aria-label="Permalink to &quot;34. 如何看待连续涨停的股票&quot;">​</a></h2><p>我们这个市场，有大量的短线客，做短线的想的都是要做龙头，只要被市场确定为龙头，卖给谁就不再是问题，相反问题变成要买的人很多，筹码有限，所以就造成连续涨停的结果。</p><h2 id="_35-为什么要做短线" tabindex="-1">35. 为什么要做短线 <a class="header-anchor" href="#_35-为什么要做短线" aria-label="Permalink to &quot;35. 为什么要做短线&quot;">​</a></h2><p>关于长线和短线，我不否认长线的赚钱模式，但是在当前的A股市场中，短线模式确实是效率较高的一种，百万实盘赛中众多的好手就是最好的证明，其复利的增长速度让很多投资者难以相信。</p><h2 id="_36-短线一般持股多长时间" tabindex="-1">36. 短线一般持股多长时间 <a class="header-anchor" href="#_36-短线一般持股多长时间" aria-label="Permalink to &quot;36. 短线一般持股多长时间&quot;">​</a></h2><p>短的一两日，长一点的话5到10天也有。</p><h2 id="_37-如何进行试错交易" tabindex="-1">37. 如何进行试错交易 <a class="header-anchor" href="#_37-如何进行试错交易" aria-label="Permalink to &quot;37. 如何进行试错交易&quot;">​</a></h2><p>试错对应的是预判，预判不成立，就走，预判确认再加仓，和下跌多少无关，和判断的动态变化过程有关。</p><h2 id="_38-操作的核心理念是什么" tabindex="-1">38. 操作的核心理念是什么 <a class="header-anchor" href="#_38-操作的核心理念是什么" aria-label="Permalink to &quot;38. 操作的核心理念是什么&quot;">​</a></h2><p>理念的东西，简单说就是把握市场热点，实际操作中，预判、试错、确认、加仓等。</p><h2 id="_39-如何操作市场热点股票" tabindex="-1">39. 如何操作市场热点股票 <a class="header-anchor" href="#_39-如何操作市场热点股票" aria-label="Permalink to &quot;39. 如何操作市场热点股票&quot;">​</a></h2><p>（1）关于热点，有长期的主流，也有短期的支流，长期的主流能持续，可以反复做，短期的支流，爆发力强，都有可操作性。<br> （2）具体技术的东西，个人不怎么注重，虽然做的是短线，但是看的是更大的局。<br> （3）止损，不看好了就卖出，管他是不是止损。</p><h2 id="_40-短线卖点如何把握" tabindex="-1">40. 短线卖点如何把握 <a class="header-anchor" href="#_40-短线卖点如何把握" aria-label="Permalink to &quot;40. 短线卖点如何把握&quot;">​</a></h2><p>和买入是一样的，先预判减仓，再确认卖出。预期也是动态的变化过程，要结合大盘和整个市场状况。</p><h2 id="_41-如何参与大盘的超跌反弹" tabindex="-1">41. 如何参与大盘的超跌反弹 <a class="header-anchor" href="#_41-如何参与大盘的超跌反弹" aria-label="Permalink to &quot;41. 如何参与大盘的超跌反弹&quot;">​</a></h2><p>通常情况下，在下跌过程中，操作可采用两种模式：<br> （1）超跌反弹模式，选择标的通常为超跌品种，难点在于时机的把握，过早介入容易吃套，所以原则上宁愿慢三分错过，并且注意仓位的控制，反弹后快进快出。<br> （2）有新的高强度热点的，继续做主升品种，可以放弃超跌模式，而直接进行攻击性的热点操作。难点在于热点的判断，一旦判断错误，形成补跌，损失也会较大。</p><h2 id="_42-小散要怎么提高基本功-学习哪些技术素养" tabindex="-1">42. 小散要怎么提高基本功，学习哪些技术素养 <a class="header-anchor" href="#_42-小散要怎么提高基本功-学习哪些技术素养" aria-label="Permalink to &quot;42. 小散要怎么提高基本功，学习哪些技术素养&quot;">​</a></h2><p>往大了说是综合素质，什么都要知道点，但是实际上到后来，什么技术啊，基本面的都不重要，到了那个阶段，k线看一眼，就决定操作了。</p><h2 id="_43-如何追涨大涨的板块" tabindex="-1">43. 如何追涨大涨的板块 <a class="header-anchor" href="#_43-如何追涨大涨的板块" aria-label="Permalink to &quot;43. 如何追涨大涨的板块&quot;">​</a></h2><p>通常情况下，直接追龙头，或者买涨幅不大的有潜力的都可以，具体看你的判断了。</p><h2 id="_44-如何控制持股的心态" tabindex="-1">44. 如何控制持股的心态 <a class="header-anchor" href="#_44-如何控制持股的心态" aria-label="Permalink to &quot;44. 如何控制持股的心态&quot;">​</a></h2><p>心态问题，我只能说，情绪是情绪，操作是操作，获利兑现和恐惧亏损是人的天性，但是作为职业投资者应该克服这些，迫切也好恐惧也好，操作该怎么还是怎么，如果让情绪影响了操作，便不该了。其中最大的忌讳就是亏钱了就急于翻本，乱操作一气，容易错上加错，后果严重。</p><h2 id="_45-我想完善一下交易系统-给自己加个3-的止损线可以吗" tabindex="-1">45. 我想完善一下交易系统，给自己加个3%的止损线可以吗 <a class="header-anchor" href="#_45-我想完善一下交易系统-给自己加个3-的止损线可以吗" aria-label="Permalink to &quot;45. 我想完善一下交易系统，给自己加个3%的止损线可以吗&quot;">​</a></h2><p>我没有止损这个概念，不看好了卖出就是了，3%这样的过于教条。</p><h2 id="_46-通过集合竞价寻找强势股-在开盘时买入-要注意哪些才能提高成功率" tabindex="-1">46. 通过集合竞价寻找强势股，在开盘时买入，要注意哪些才能提高成功率 <a class="header-anchor" href="#_46-通过集合竞价寻找强势股-在开盘时买入-要注意哪些才能提高成功率" aria-label="Permalink to &quot;46. 通过集合竞价寻找强势股，在开盘时买入，要注意哪些才能提高成功率&quot;">​</a></h2><p>9:30买股，前一天封死涨停买不到的龙头品种，或者利好消息刺激的品种，前一种需要对热点的持续性有判断，后一种需要对消息敏感。</p><h2 id="_47-如何通过尾盘买入个股-在第二天上午延续冲高的惯性中获利出局" tabindex="-1">47. 如何通过尾盘买入个股，在第二天上午延续冲高的惯性中获利出局 <a class="header-anchor" href="#_47-如何通过尾盘买入个股-在第二天上午延续冲高的惯性中获利出局" aria-label="Permalink to &quot;47. 如何通过尾盘买入个股，在第二天上午延续冲高的惯性中获利出局&quot;">​</a></h2><p>尾盘买股，预期热点第二天持续的品种，需要对热点的持续性有判断。</p><h2 id="_48-买股的时候要注意什么才能提高成功率" tabindex="-1">48. 买股的时候要注意什么才能提高成功率 <a class="header-anchor" href="#_48-买股的时候要注意什么才能提高成功率" aria-label="Permalink to &quot;48. 买股的时候要注意什么才能提高成功率&quot;">​</a></h2><p>做的是短线，看的是更大的局。更大的局，简单说，就是一个股票10元买的时候，看的应该是15或者20元甚至更高，实际操作中可能赚了三五个点就走了，或者割肉走了。具体技术的东西我不太关心。</p><h2 id="_49-如何理解您所说的局" tabindex="-1">49. 如何理解您所说的局 <a class="header-anchor" href="#_49-如何理解您所说的局" aria-label="Permalink to &quot;49. 如何理解您所说的局&quot;">​</a></h2><p>这个局，是个综合因素，政策面、技术面、基本面、资金面、人气面等集于一身而形成的共振。</p><h2 id="_50-股票卖出后-结果继续上涨-该怎么办" tabindex="-1">50. 股票卖出后，结果继续上涨，该怎么办 <a class="header-anchor" href="#_50-股票卖出后-结果继续上涨-该怎么办" aria-label="Permalink to &quot;50. 股票卖出后，结果继续上涨，该怎么办&quot;">​</a></h2><p>已经卖出了，赚我该赚的就可以了，有时候卖出未必不看好，只是有更好的品种。做短线追求的是买入后短期就能爆发上涨的品种。</p><h2 id="_51-上涨空间是根据什么判断的" tabindex="-1">51. 上涨空间是根据什么判断的 <a class="header-anchor" href="#_51-上涨空间是根据什么判断的" aria-label="Permalink to &quot;51. 上涨空间是根据什么判断的&quot;">​</a></h2><p>热点、政策、人气等多因素的集合。</p><h2 id="_52-新手经常犯的错误有哪些" tabindex="-1">52. 新手经常犯的错误有哪些 <a class="header-anchor" href="#_52-新手经常犯的错误有哪些" aria-label="Permalink to &quot;52. 新手经常犯的错误有哪些&quot;">​</a></h2><p>（1）在指数高位迷恋价值投资，越跌越买，结果遭遇暴跌，最后损失惨重。<br> （2）在短线初级阶段迷恋技术，经常买突破新高的股，结果赚么赚点小钱，碰到几个假突破就亏大了。<br> （没有市场理解力，没有内功，只迷恋浮于表面的技术终究不行）</p><h2 id="_53-如何让自己在操作上进一步提高" tabindex="-1">53. 如何让自己在操作上进一步提高 <a class="header-anchor" href="#_53-如何让自己在操作上进一步提高" aria-label="Permalink to &quot;53. 如何让自己在操作上进一步提高&quot;">​</a></h2><p>原来是把简单的变复杂，现在是把复杂的变简单。<br> 股市带给我的一方面是自由的生活，不断丰富的物质，另一方面就是技术水平不断提高后思想境界的升华。</p><h2 id="_54-如何看待突破新高后的买入" tabindex="-1">54. 如何看待突破新高后的买入 <a class="header-anchor" href="#_54-如何看待突破新高后的买入" aria-label="Permalink to &quot;54. 如何看待突破新高后的买入&quot;">​</a></h2><p>（1）摆脱教条主义的束缚，实践才是检验真理的唯一标准，多思考和总结自己成功例子的共性和失败例子的共性，成功的例子里面再思考能不能更早一点下手，未必要等突破以后。<br> （2）突破买入虽然也不失为一种不错的方法，但是还处在见招拆招的阶段，如果你能看到更大的局，应该追求未出招已应招的境界。</p><h2 id="_55-股票从持仓盈利变为持仓亏损后-应该如何止损" tabindex="-1">55. 股票从持仓盈利变为持仓亏损后，应该如何止损 <a class="header-anchor" href="#_55-股票从持仓盈利变为持仓亏损后-应该如何止损" aria-label="Permalink to &quot;55. 股票从持仓盈利变为持仓亏损后，应该如何止损&quot;">​</a></h2><p>（1）操作应简单化，不要想法太多，临盘难免犹豫，另外有太重的成本障碍，这些都于操作不利。<br> （2）先克服心理障碍，之后多操作，多思考，概率会告诉你以后应该怎么做，如果不能克服心理障碍，再多的失败也不能转化为经验。</p><h2 id="_56-为什么您拿的股票总能大涨" tabindex="-1">56. 为什么您拿的股票总能大涨 <a class="header-anchor" href="#_56-为什么您拿的股票总能大涨" aria-label="Permalink to &quot;56. 为什么您拿的股票总能大涨&quot;">​</a></h2><p>不要只盯着我的账户，如果只看账户，我都不相信自己有这样快的增长速度。看理念，如果你有好的理念，赚再多都没什么好奇怪的。<br> 以前我也不信Asking是亿万身家的，后来领会了他的只言片语，恍然大悟，只恨看到的太晚。</p><h2 id="_57-asking给你最大的启示是什么" tabindex="-1">57. Asking给你最大的启示是什么 <a class="header-anchor" href="#_57-asking给你最大的启示是什么" aria-label="Permalink to &quot;57. Asking给你最大的启示是什么&quot;">​</a></h2><p>行情好，多做；行情不好，多休息；选股就选大众情人。</p><h2 id="_58-发现买错被套怎么办" tabindex="-1">58. 发现买错被套怎么办 <a class="header-anchor" href="#_58-发现买错被套怎么办" aria-label="Permalink to &quot;58. 发现买错被套怎么办&quot;">​</a></h2><p>（1）预判，买入。<br> （2）确认，加仓。<br> （3）热点转换，换股。<br> （4）不再看好，卖出。<br> 操作还是一样，和套几个点没有关系，如果你还是看好，那就等等，不看好就卖出或者换股。因为简单，所以果断。最忌自己都不看好了，只是因为套了几个点，还在犹豫。</p><h2 id="_59-如何第一时间发现市场热点" tabindex="-1">59. 如何第一时间发现市场热点 <a class="header-anchor" href="#_59-如何第一时间发现市场热点" aria-label="Permalink to &quot;59. 如何第一时间发现市场热点&quot;">​</a></h2><p>多看涨幅榜和异动榜的共性。</p><h2 id="_60-关于仓位问题-上多少仓位这个是以什么为标准" tabindex="-1">60. 关于仓位问题，上多少仓位这个是以什么为标准 <a class="header-anchor" href="#_60-关于仓位问题-上多少仓位这个是以什么为标准" aria-label="Permalink to &quot;60. 关于仓位问题，上多少仓位这个是以什么为标准&quot;">​</a></h2><p>仓位和风险收益比有关，机会越大仓位越高，风险越大仓位越低。</p><h2 id="_61-你在不看好大盘的情况下会不会继续操作" tabindex="-1">61. 你在不看好大盘的情况下会不会继续操作 <a class="header-anchor" href="#_61-你在不看好大盘的情况下会不会继续操作" aria-label="Permalink to &quot;61. 你在不看好大盘的情况下会不会继续操作&quot;">​</a></h2><p>大盘与个股是相辅相成的，大盘不看好的情况下，注重的是风险，有高强度的板块的情况下，注重的是机会，如果既不看好大盘，又没有热点，就多休息吧，如果有强热点，则仍可参与操作。</p><h2 id="_62-如何判断领涨股合力是否会继续加大或者持续" tabindex="-1">62. 如何判断领涨股合力是否会继续加大或者持续 <a class="header-anchor" href="#_62-如何判断领涨股合力是否会继续加大或者持续" aria-label="Permalink to &quot;62. 如何判断领涨股合力是否会继续加大或者持续&quot;">​</a></h2><p>我喜欢用更大的局来看待合力，如果判断领涨的是个股行为，本身具有较大的不确定性。如果同一概念的两个领涨股同时开始上冲，上冲过程中，其中一个已经开始滞涨或者下探，出现这样的状况，及时卖出规避风险是合理的，除非你对这个局有较大的预判。</p><h2 id="_63-如何衡量一位职业选手是否优秀" tabindex="-1">63. 如何衡量一位职业选手是否优秀 <a class="header-anchor" href="#_63-如何衡量一位职业选手是否优秀" aria-label="Permalink to &quot;63. 如何衡量一位职业选手是否优秀&quot;">​</a></h2><p>我认为衡量一个职业选手最重要的指标就是盈利的稳定性。短线选手普遍存在的问题是无法控制回撤。在行情偏弱时，应该注意控制风险。如果有较大的回撤，说明你需要注重弱势阶段的风险控制。尽量争取1年中10个月以上是盈利的，就本人而言如果我没记错的话，去年到现在，只有去年因为特停造成过一次单月亏损，今年到现在所有的月份全部实现盈利，正是因为这种稳定性，才是我资金不断增长的根本，对此我非常注重。<br> （控制回撤是职业选手第一要务，复利是世界第八大奇迹）</p><h2 id="_64-如何区分政策驱动和人气驱动的股票" tabindex="-1">64. 如何区分政策驱动和人气驱动的股票 <a class="header-anchor" href="#_64-如何区分政策驱动和人气驱动的股票" aria-label="Permalink to &quot;64. 如何区分政策驱动和人气驱动的股票&quot;">​</a></h2><p>（1）政策面相对是独立，市场会相对围绕政策反复炒作，这是中国股市的特色。<br> （2）人气面也是一个循环的过程，这个和市场的赚钱效应有关，股神遍地的时候就是人气最旺的时候。<br> （3）不知道上涨原因的股票要么就找到他上涨的原因，找不到就不用管它，赚自己看到懂的钱就够了。</p><h2 id="_65-有什么股票类的书籍推荐吗" tabindex="-1">65. 有什么股票类的书籍推荐吗 <a class="header-anchor" href="#_65-有什么股票类的书籍推荐吗" aria-label="Permalink to &quot;65. 有什么股票类的书籍推荐吗&quot;">​</a></h2><p>股票方面的书，看过的非常非常多，不过以现在的理解，绝大部分都是误人子弟的，所以也不多说了。</p><h2 id="_66-看龙虎榜成交回报是否有用" tabindex="-1">66. 看龙虎榜成交回报是否有用 <a class="header-anchor" href="#_66-看龙虎榜成交回报是否有用" aria-label="Permalink to &quot;66. 看龙虎榜成交回报是否有用&quot;">​</a></h2><p>（1）知己知彼，百战百胜，成交回报是股市资讯的一部分，有助于心理分析，你对对手的心理足够的了解，操作上就更容易把握主动。<br> （2）有用，但要了解的更全面，光靠这个来判断操作是不够的。</p><h2 id="_67-什么是短线赚钱效应" tabindex="-1">67. 什么是短线赚钱效应 <a class="header-anchor" href="#_67-什么是短线赚钱效应" aria-label="Permalink to &quot;67. 什么是短线赚钱效应&quot;">​</a></h2><p>我是做短线的，所指的赚钱效应，以短为主，大致展开如下：<br> （1）这个市场上有大量的短线选手，很多人其实对市场理解的不够，但是他们在某个阶段也会赚钱，这种赚钱效应会增加他们的自信，进而快速的投入到下一个品种上，当这种行为产生群体效应时，这种背景下热点就容易有持续性。<br> （2）相反的，如果短线追涨的那些，接二连三的失手，导致资金大幅回落，他们就会进入反思，从而减少操作，当这种行为产生群体效应时，一些强势股没有后继者，就容易形成补跌。<br> （3）这两种心理变化过程，不断循环往复，踏准了节奏，就能分辨出机会的大小，进而决定进出的仓位。</p><h2 id="_68-怎么区分一个热点是主流热点还是短期热点" tabindex="-1">68. 怎么区分一个热点是主流热点还是短期热点 <a class="header-anchor" href="#_68-怎么区分一个热点是主流热点还是短期热点" aria-label="Permalink to &quot;68. 怎么区分一个热点是主流热点还是短期热点&quot;">​</a></h2><p>市场在不断下跌的时候，会有一些股票还能创新高，这些冒头的如果被杀了，其他人看着脚也会发软，但是这些冒头的不断的赚钱，后面就会有资金开始前赴后继，此时介入相对安全。那些成批的创新高的或者近期连续大涨的股票所具有的最多的共性就是热点。</p><h2 id="_69-我经常买在高位遇到大跌被套牢-然后越跌越买或者持股不动-怎么办" tabindex="-1">69. 我经常买在高位遇到大跌被套牢，然后越跌越买或者持股不动，怎么办 <a class="header-anchor" href="#_69-我经常买在高位遇到大跌被套牢-然后越跌越买或者持股不动-怎么办" aria-label="Permalink to &quot;69. 我经常买在高位遇到大跌被套牢，然后越跌越买或者持股不动，怎么办&quot;">​</a></h2><p>为什么高点买入后碰到大跌，就拿着中线不动，这是一个心理障碍，说好听点是不愿意认输，觉得卖出了就是输钱了，说不好听点是虚荣心在作怪，操作上应该理性的来应对：<br> （1）大盘还有个股所在的板块是阶段见顶还是上涨中继？如果判断阶段见顶，应该果断卖出。<br> （2）如果看反弹，则预判反弹的热点还是手上的股票所在的板块吗？如果不是，应该果断卖出，换入新的热点。<br> （3）很多人套牢了总是想着反弹，但是实际情况往往即使反弹了，手上的股票也未必能反弹多少，如果你有时间关心自己套着的股票什么时候解套，不如关心下一个热点是什么。</p><h2 id="_70-亏了钱-心情很差怎么办" tabindex="-1">70. 亏了钱，心情很差怎么办 <a class="header-anchor" href="#_70-亏了钱-心情很差怎么办" aria-label="Permalink to &quot;70. 亏了钱，心情很差怎么办&quot;">​</a></h2><p>（1）心情归心情，操作归操作，这是两码事，千万不要因为心情影响操作。<br> （2）重新振作起来，用新的眼光来审视这个市场，而不是拘泥于自己套牢的股票。<br> （3）关于大盘的判断，其实不重要，重要的是操作，职业炒手和just999这样的高手在股指期货亏损严重，他们对大盘的判断一塌糊涂，然而即便这样，股市仍然是他们的提款机。<br> （4）你拿着股票期待这里是底，即便这里真的是底又如何，未来领先反弹的股票也未必是你手上的股。<br> （5）学会一套完善的系统，才能做永远的赢家。我没法知道明天大盘是涨是跌，但好的操作可以做到的是：如果大盘上涨，我的股票大涨，如果大盘下跌，我的股票不跌或者小跌，如此反复，积小胜为大胜。<br> （6）是赢是亏有时候不重要，重要的是做对，盈亏的事情交给概率。</p><h2 id="_71-大盘不好的时候-是干脆不做的好-还是小仓位一直做好呢" tabindex="-1">71. 大盘不好的时候，是干脆不做的好，还是小仓位一直做好呢 <a class="header-anchor" href="#_71-大盘不好的时候-是干脆不做的好-还是小仓位一直做好呢" aria-label="Permalink to &quot;71. 大盘不好的时候，是干脆不做的好，还是小仓位一直做好呢&quot;">​</a></h2><p>大盘不好的时候，不做也可以，小仓做也可以，如果你是老手了，不做光看也可以感受市场的变化，如果你是新手，多亏些或许能增长点经验也好，看你的具体情况了。</p><h2 id="_72-时常激发自己的贪念-造成做错的概率很高-不做又怕失去盘感-怎么办" tabindex="-1">72. 时常激发自己的贪念，造成做错的概率很高，不做又怕失去盘感，怎么办 <a class="header-anchor" href="#_72-时常激发自己的贪念-造成做错的概率很高-不做又怕失去盘感-怎么办" aria-label="Permalink to &quot;72. 时常激发自己的贪念，造成做错的概率很高，不做又怕失去盘感，怎么办&quot;">​</a></h2><p>贪念这个，既然知道就要去克服，赚钱的人说白了赚的就是这样人的钱，克服的一个方法就是时刻提醒自己，操作是操作，情绪是情绪，永远不要让情绪来影响你的操作。</p><h2 id="_73-如何选股-买股时看什么指标" tabindex="-1">73. 如何选股，买股时看什么指标 <a class="header-anchor" href="#_73-如何选股-买股时看什么指标" aria-label="Permalink to &quot;73. 如何选股，买股时看什么指标&quot;">​</a></h2><p>我是做短线的，所以选股而言，要么是当前的热门，要么是预判会成为热门的品种，基本不看任何技术指标。</p><h2 id="_74-跟着买入强势股-当天被套-第二天继续吃面-怎么办" tabindex="-1">74. 跟着买入强势股，当天被套，第二天继续吃面，怎么办 <a class="header-anchor" href="#_74-跟着买入强势股-当天被套-第二天继续吃面-怎么办" aria-label="Permalink to &quot;74. 跟着买入强势股，当天被套，第二天继续吃面，怎么办&quot;">​</a></h2><p>有些强势票是个股行为，往往有较大的不确定性，对于板块性的行为，大体上有个规律，如果你是有心人，耐心总结，你会发现这样的规律，以后自然知道要怎么做（比如论坛上貌貂御龙、板块共振这样的对涨停的分析和总结，我觉得就很好）。</p><h2 id="_75-被套之后-是应该止损还是等企稳后补仓" tabindex="-1">75. 被套之后，是应该止损还是等企稳后补仓 <a class="header-anchor" href="#_75-被套之后-是应该止损还是等企稳后补仓" aria-label="Permalink to &quot;75. 被套之后，是应该止损还是等企稳后补仓&quot;">​</a></h2><p>关于补仓以及止损这样的问题，我的回答是：你还有补仓或者止损的想法，就说明你的心理还有成本这个障碍，好的操作，应该是最简单的，只有买入或者卖出。</p><h2 id="_76-如何判断一个概念是否会走主升浪" tabindex="-1">76. 如何判断一个概念是否会走主升浪 <a class="header-anchor" href="#_76-如何判断一个概念是否会走主升浪" aria-label="Permalink to &quot;76. 如何判断一个概念是否会走主升浪&quot;">​</a></h2><p>概念的挖掘我觉得要有一个综合性的考量，包括政策面、资金面、人气面、技术面、基本面，在市场的资金和人气较弱的时候，难以启动主升浪的品种，所以那些相对高位的品种，较难得到市场的认可，操作上应该谨慎。</p><h2 id="_77-如何判断自己手中的股票是该卖出还是继续持有" tabindex="-1">77. 如何判断自己手中的股票是该卖出还是继续持有 <a class="header-anchor" href="#_77-如何判断自己手中的股票是该卖出还是继续持有" aria-label="Permalink to &quot;77. 如何判断自己手中的股票是该卖出还是继续持有&quot;">​</a></h2><p>对此我的方法就是问自己，如果我现在是空仓的话，我会怎么办？<br> （1）如果我是空仓我就什么也不买，那么就卖出手上的个股。<br> （2）如果我是空仓我会买其他的股，那么就换股。<br> （3）如果我是空仓我还是会买自己手上的股，那么就不要卖了。<br> 当然以上问题只是方向性的问题，还有个量化的要求，比如如果空仓也只是考虑少量买自己手上的股的话，那么至少现在是重仓的话也要减仓。</p><h2 id="_78-大盘处于下跌趋势时的市场判断与操作策略" tabindex="-1">78. 大盘处于下跌趋势时的市场判断与操作策略 <a class="header-anchor" href="#_78-大盘处于下跌趋势时的市场判断与操作策略" aria-label="Permalink to &quot;78. 大盘处于下跌趋势时的市场判断与操作策略&quot;">​</a></h2><p>（1）下跌趋势，谨慎为上，保住本金为主，等市场由弱转强时才是奋力搏击利润的时候。<br> （2）下跌趋势各阶段的炒作模式：<br> 1&gt; 初期，以仍有主升能力的品种为主，或者可以等回落后再做一波。<br> 2&gt; 第二阶段，大部分强势品种已经在高位且有二次确认见顶嫌疑，选择大周期超跌品种。<br> 3&gt; 第三阶段，强势品种大幅回落，大周期超跌品种完成反弹，在当前市场阶段，可以参与部分个股性机会，耐心等待市场由弱转强时的暴利机会。<br> 4&gt; 末段，市场恐慌心理极度扩散，谈股色变，大部分个股下跌惨重，之后会出来一个有持续性的热点来领导市场上涨，但是这个板块要求同时在政策面、技术面、资金面形成共振，例如1664之后的水泥，这个由弱转强的阶段，将是短线投资者奋力博取利润的绝佳机会，之后若市场确认进入上升趋势，则开始热点间的滚动操作。</p><h2 id="_79-下跌趋势中-如何进行低吸" tabindex="-1">79. 下跌趋势中，如何进行低吸 <a class="header-anchor" href="#_79-下跌趋势中-如何进行低吸" aria-label="Permalink to &quot;79. 下跌趋势中，如何进行低吸&quot;">​</a></h2><p>和个人的操作模式有关，下跌趋势阶段，通常是大跌小回，最为紧要的原则就是要规避大盘大跌带来的系统性风险，因此选择在大盘大跌，股指远离5日线时进行买入操作，再结合大盘下跌所处的阶段，寻找相应的标的进行出击。</p><h2 id="_80-如何看待价值投资" tabindex="-1">80. 如何看待价值投资 <a class="header-anchor" href="#_80-如何看待价值投资" aria-label="Permalink to &quot;80. 如何看待价值投资&quot;">​</a></h2><p>（1）股市的真理个人认为在于价值投资，在任何市场，只有价值投资才是致胜的唯一方法。在最初的短线迷茫后，有5年多的时间，我认同上述观点，后来看到Asking、职业炒手等人觉得我们这里不能搞价值投资。但当我有一天觉得可以短线稳定赚钱的时候，发现还是价值投资的理念还是对的。<br> （2）问题在于对于价值的认知，据说在民国时期一根金条可以买一个四合院，现在可能买一个卫生间都困难，那房子和金条到底什么样的比例才符合价值，把眼光看的更长久一点，价值是人心定的，而人心是会变化的。<br> （3）就股票而言，茅台酒本质是水，但是大家喜欢喝，所以可以卖高价，现在买茅台的人是价值投资，是因为认为这个水未来会有更多的人喜欢。现在买高铁股票的人，同样可以因为认为未来有更多的人喜欢买高铁的股票，本质是一样的，区别在于时间的长短。<br> （4）我做短线，并不否认长线，我学习Asking，我也崇拜巴菲特。长线和短线都可以赚钱，重要的是你对市场真理的理解，不过当前市场而言个人觉得更适合短线，10年20年后的市场又会变的怎样，未知，但是有一点是肯定的，价值投资是唯一不变的真理。</p><h2 id="_81-如何看待投资与投机" tabindex="-1">81. 如何看待投资与投机 <a class="header-anchor" href="#_81-如何看待投资与投机" aria-label="Permalink to &quot;81. 如何看待投资与投机&quot;">​</a></h2><p>关于投资和投机、长线和短线，在很长的一段时间内都是让我困惑的一个问题，后来这个问题想通了，徐翔胜过但斌，不是敢死队胜过巴菲特，而是徐翔比但斌更懂在中国什么才是巴菲特。</p><h2 id="_82-个人对短线的认知" tabindex="-1">82. 个人对短线的认知 <a class="header-anchor" href="#_82-个人对短线的认知" aria-label="Permalink to &quot;82. 个人对短线的认知&quot;">​</a></h2><p>（1）短线是一种综合技能，很多人花了大量的时间研究技术或者政策面或者基本面等等，结果都不得其门而入，天道酬勤，但也应懂得如何综合使用。<br> （2）善于做短线的人，应该清楚自身的特点，寻找出适合自己的方法。<br> （3）当时机不成熟或者市场对自己不利时，理性的面对风险，当机会来临时，全力拼取。这句话理解不难，做到却不易，很多人往往因为亏钱就想着急于扳回，一再对抗风险，机会来临时却又麻木于自己深套中的个股。<br> （4）当市场的发展和自己的预判不一致时，要重新审视，越是关键时刻，越要冷静处理，平稳的心态是做短线的根本。<br> （5）信念。曾经很长的时间迷茫过，所以懂得信念的重要，自强不息，百折不回。</p><h2 id="_83-出击仓位和赢面的关系如何划分" tabindex="-1">83. 出击仓位和赢面的关系如何划分 <a class="header-anchor" href="#_83-出击仓位和赢面的关系如何划分" aria-label="Permalink to &quot;83. 出击仓位和赢面的关系如何划分&quot;">​</a></h2><p>赢面60%以下，观望。<br> 赢面60%-70%，小仓出击。<br> 赢面70%-80%，中仓出击。<br> 赢面80%-90%，大仓出击。<br> 赢面90%以上，满仓出击。<br> 这个赢面包括胜率和涨跌空间比。<br> 譬如满仓出击时，对我来说必须满足以下两个条件才会做这样的决策，一方面是胜率要求90%以上，另一方面是上涨的空间和下跌的空间比率，上涨的空间至少要看到30%-50%以上，而下跌的空间应该在3%-5%以内。尽力把握好操作，胜负的事情交给概率，不管结果如何坦然面对，冷静处理。</p><h2 id="_84-如何控制交易的频次" tabindex="-1">84. 如何控制交易的频次 <a class="header-anchor" href="#_84-如何控制交易的频次" aria-label="Permalink to &quot;84. 如何控制交易的频次&quot;">​</a></h2><p>市场弱势时自然机会就少，市场强势时，60%以上赢面的机会较多，接近每天交易。重仓出击相对少些，平均一年十几次左右，其中4-5次10%以上的获利，包括1-2次20%以上，亏损10%控制在1次或杜绝。没有具体统计过，感觉大致如此，反应在收益率曲线上，就是平时稳攀升为主，偶尔跳跃式上扬，极少大幅回落。<br> 知易行难，我有个朋友也做短线，追龙头为主，刚开始大家都是几十万，行情好的时候，他主动和我比收益率，经常超过我，行情不好的时候就听不到他的声音，现在他还是几十万。</p><h2 id="_85-您参与的都是龙头股吗" tabindex="-1">85. 您参与的都是龙头股吗 <a class="header-anchor" href="#_85-您参与的都是龙头股吗" aria-label="Permalink to &quot;85. 您参与的都是龙头股吗&quot;">​</a></h2><p>随着自己交易模式的不断优化，确实操作上略有变化，不过绝对不能说是只做龙头股和强势股，本人风格偏保守，不愿意承担高风险，不过在自认为确定性和持续性较高的主流热点机会面前才会重仓参与所谓的龙头股。</p><h2 id="_86-我每个月稳定盈利5-是否应该更激进一些" tabindex="-1">86. 我每个月稳定盈利5%，是否应该更激进一些 <a class="header-anchor" href="#_86-我每个月稳定盈利5-是否应该更激进一些" aria-label="Permalink to &quot;86. 我每个月稳定盈利5%，是否应该更激进一些&quot;">​</a></h2><p>你能每个月稳定盈利5%，已经非常之好了。先保持，不用更激进，不断优化自己的模式，根据不同阶段按照不同方法操作就可以，目标太高，一旦不能达成，会影响情绪。</p><h2 id="_87-您是多少钱开始做股票的" tabindex="-1">87. 您是多少钱开始做股票的 <a class="header-anchor" href="#_87-您是多少钱开始做股票的" aria-label="Permalink to &quot;87. 您是多少钱开始做股票的&quot;">​</a></h2><p>一万元起步。</p><h2 id="_88-散户应该选择价值投资还是短线投机" tabindex="-1">88. 散户应该选择价值投资还是短线投机 <a class="header-anchor" href="#_88-散户应该选择价值投资还是短线投机" aria-label="Permalink to &quot;88. 散户应该选择价值投资还是短线投机&quot;">​</a></h2><p>（1）对于企业价值的研究，和那些经济学博士硕士的基金经理相比，他们有团队，信息丰富及时，还能去上市公司调研，如果你也搞这个你的优势在哪里？<br> （2）短线的话，如果你对市场理解够深，资金量越小，收益率越高，1000w以下的，做的好的，都可以轻松超过国内所有的公募基金，也许你喜欢你理解的价值分析，但是我们当前这个市场做短线相对有利。</p><h2 id="_89-如何追击热点板块的强势股" tabindex="-1">89. 如何追击热点板块的强势股 <a class="header-anchor" href="#_89-如何追击热点板块的强势股" aria-label="Permalink to &quot;89. 如何追击热点板块的强势股&quot;">​</a></h2><p>（1）先预判热点性质，是主流热点，还是次主流热点还是非主流热点。<br> （2）预判可以先试错轻仓买入，确认后再追涨加仓。<br> （3）对于主流热点，实盘操作中可以直接买相对确定的龙头也可以买后发品种，仓位稍重些也无妨。<br> （4）若是次主流，有绝佳机会也可以重仓搏杀，若是非主流，轻仓参与，隔日卖出。</p><h2 id="_90-在人气很高的时候是否可以重仓操作" tabindex="-1">90. 在人气很高的时候是否可以重仓操作 <a class="header-anchor" href="#_90-在人气很高的时候是否可以重仓操作" aria-label="Permalink to &quot;90. 在人气很高的时候是否可以重仓操作&quot;">​</a></h2><p>好的短线操作，人气高的时候，重仓操作无妨，若是市场强势依旧，可获取暴利，若是市场恰巧面临转折，也可全身而退。</p><h2 id="_91-买入和卖出有没有什么周期" tabindex="-1">91. 买入和卖出有没有什么周期 <a class="header-anchor" href="#_91-买入和卖出有没有什么周期" aria-label="Permalink to &quot;91. 买入和卖出有没有什么周期&quot;">​</a></h2><p>买入机会，卖出风险，没有周期。</p><h2 id="_92-自己回撤幅度很大怎么办-怎么控制风险" tabindex="-1">92. 自己回撤幅度很大怎么办，怎么控制风险 <a class="header-anchor" href="#_92-自己回撤幅度很大怎么办-怎么控制风险" aria-label="Permalink to &quot;92. 自己回撤幅度很大怎么办，怎么控制风险&quot;">​</a></h2><p>（1）风险控制意味着放弃机会，看舍与得的衡量，以最近的操作来说，上周五我是等地产板块的前三个都涨停的时候，确认强度再排队买股，所幸买到了第四个涨停的，今天涨停全出，因为有确定性，所以风险小，缺点是可能买不到而失去机会。比如今天的煤炭股，看着最强的涨停，但是等确认的时候，封单已经非常巨大，之后排队，至收盘未成交。<br> （2）一字板重仓是我另一个杀手锏，我的保守策略恰好又为我提供了一字板重仓买入的机会，这一方法屡试不爽。<br> （3）最锐的矛（一字重仓）+最强的盾（放弃风险，买入确定），我的两个强项正好互相搭配，在很大程度上帮助我既能稳定获利，又能控制回撤，但是未必适合所有人。</p><h2 id="_93-怎么判断某个热点可以持续还是一日游" tabindex="-1">93. 怎么判断某个热点可以持续还是一日游 <a class="header-anchor" href="#_93-怎么判断某个热点可以持续还是一日游" aria-label="Permalink to &quot;93. 怎么判断某个热点可以持续还是一日游&quot;">​</a></h2><p>大局观，这是道的范畴，尽量培养自己站在更高的高度看整个市场。</p><h2 id="_94-股票交易的最优化模式" tabindex="-1">94. 股票交易的最优化模式 <a class="header-anchor" href="#_94-股票交易的最优化模式" aria-label="Permalink to &quot;94. 股票交易的最优化模式&quot;">​</a></h2><p>（1）各市场高手所完成阶段资金积累需要的年限：</p><table tabindex="0"><thead><tr><th style="text-align:left;">资金量</th><th style="text-align:left;">长线投资</th><th style="text-align:left;">短线投机</th></tr></thead><tbody><tr><td style="text-align:left;">十万</td><td style="text-align:left;">0</td><td style="text-align:left;">0</td></tr><tr><td style="text-align:left;">百万</td><td style="text-align:left;">10</td><td style="text-align:left;">2.5</td></tr><tr><td style="text-align:left;">千万</td><td style="text-align:left;">10</td><td style="text-align:left;">3</td></tr><tr><td style="text-align:left;">亿</td><td style="text-align:left;">10</td><td style="text-align:left;">4.5</td></tr><tr><td style="text-align:left;">十亿</td><td style="text-align:left;">12</td><td style="text-align:left;">15</td></tr><tr><td style="text-align:left;">百亿</td><td style="text-align:left;">15</td><td style="text-align:left;">100</td></tr></tbody></table><p>（2）所谓长线与短线，价值与投机，在本人的认识中，是可以统一的，考虑市场大众对此的区分理解，暂对此分拆分析。<br> （3）表格假设投资者以十万起家，长线价值投资者收益率参考巴菲特，短线投机者收益率参考A股短线高手。<br> （4）短线投机者在初始阶段有较高的效率，高手从十万到亿，可以在10年内达成，但在后期资金规模会大大影响到收益率，十亿之后若不及时转型，收益率将大为迟滞。<br> （5）长线投资者冲击成本相对较低，在后期仍可以保持相对的复利，完成百亿积累大致需要57年，有生之年有望达成。<br> （6）短线收益率目前仅对国内A股有效，不适用其他市场，长线收益率适用于全球任何市场。<br> （7）国内A股投资者，若有较高的目标，较好的策略是先让自己快速成长为短线高手，然后用10年左右时间完成上亿的积累，之后转型中长线，谋求更好的发展。<br> （8）长线价值投资者需要有企业家的素质，对于宏观和微观有敏锐的洞察力，很多草根出身的短线高手长时间关注市场后可能勉为其难。<br> （9）对于入市不长的短线爱好者先泼些冷水，纯k线技术的打板，统计胜率约在45%左右，简单所谓的追龙头模式，胜率也大抵如此，大致于澳门赌场，如此反复只会吞噬你的本金。<br> （10）短线操作需要较强的综合素质，包括冷静理智的心理，良好的大局观，完善的交易系统。</p><h2 id="_95-什么样的涨停板容易被砸" tabindex="-1">95. 什么样的涨停板容易被砸 <a class="header-anchor" href="#_95-什么样的涨停板容易被砸" aria-label="Permalink to &quot;95. 什么样的涨停板容易被砸&quot;">​</a></h2><p>（1）不符合主流热点的；<br> （2）不明原因的；<br> （3）累计涨幅过大的。</p><h2 id="_96-形成自己的系统能稳定赢利-需要多少年" tabindex="-1">96. 形成自己的系统能稳定赢利，需要多少年 <a class="header-anchor" href="#_96-形成自己的系统能稳定赢利-需要多少年" aria-label="Permalink to &quot;96. 形成自己的系统能稳定赢利，需要多少年&quot;">​</a></h2><p>个人炒股以来一直致力于交易模式的优化，经历十余年，有幸一朝顿悟。</p><h2 id="_97-遇到大盘整体低迷的时候-短线也很难做-怎么办" tabindex="-1">97. 遇到大盘整体低迷的时候，短线也很难做，怎么办 <a class="header-anchor" href="#_97-遇到大盘整体低迷的时候-短线也很难做-怎么办" aria-label="Permalink to &quot;97. 遇到大盘整体低迷的时候，短线也很难做，怎么办&quot;">​</a></h2><p>连续低迷阶段确实难有作为，但是碰上好的光景，一年十倍也有机会，不一概而论了。</p><h2 id="_98-对以后的短线市场如何看待" tabindex="-1">98. 对以后的短线市场如何看待 <a class="header-anchor" href="#_98-对以后的短线市场如何看待" aria-label="Permalink to &quot;98. 对以后的短线市场如何看待&quot;">​</a></h2><p>确实不知道，不过博弈的本身就是在动态的变化过程中，时刻寻求最优化的策略。</p><h2 id="_99-选到好股-为什么总拿不住" tabindex="-1">99. 选到好股，为什么总拿不住 <a class="header-anchor" href="#_99-选到好股-为什么总拿不住" aria-label="Permalink to &quot;99. 选到好股，为什么总拿不住&quot;">​</a></h2><p>买入机会，卖出风险，只做对的交易，胜负交给概率，多一份淡定，少一份胜负心。</p><h2 id="_100-技术形态看好-但基本面和消息面都不怎么样-您是否会买进" tabindex="-1">100. 技术形态看好，但基本面和消息面都不怎么样，您是否会买进 <a class="header-anchor" href="#_100-技术形态看好-但基本面和消息面都不怎么样-您是否会买进" aria-label="Permalink to &quot;100. 技术形态看好，但基本面和消息面都不怎么样，您是否会买进&quot;">​</a></h2><p>只是技术形态看好，就算买，也是轻仓，放弃也不可惜。</p><h2 id="_101-如何看待涨停板买入法" tabindex="-1">101. 如何看待涨停板买入法 <a class="header-anchor" href="#_101-如何看待涨停板买入法" aria-label="Permalink to &quot;101. 如何看待涨停板买入法&quot;">​</a></h2><p>（1）涨停板上买票的操作基本占了本人操作的一半，统计的胜率低只是针对纯技术的行为，但是不能否定，这种方法仍然是短线切实有效的方法之一。<br> （2）要有大局观，特别重仓买入的一刹那要有后市还有3到5个涨停空间的判断，巴菲特说如果你一直股票没有打算持有10年，那么一分钟也不要持有。我说一只股票如果你没有后市3-5涨停空间的判断，那么一个板也不要重仓买入。</p><h2 id="_102-强势板块的涨停股有时会出现炸板-或者一日游-怎么看" tabindex="-1">102. 强势板块的涨停股有时会出现炸板，或者一日游，怎么看 <a class="header-anchor" href="#_102-强势板块的涨停股有时会出现炸板-或者一日游-怎么看" aria-label="Permalink to &quot;102. 强势板块的涨停股有时会出现炸板，或者一日游，怎么看&quot;">​</a></h2><p>各种现象，并不一定都能得到解释，但是有些是有普遍规律性的，例如我之前说过左侧交易的好时机是连续一段下挫后的集体大幅下挫，那么对于连续上涨一段后的集体涨停就要小心了，比如近期的钢铁，虽然后期或许部分个股仍有反复，但是如果昨天大幅追高则相应需要承担一定的风险。</p><h2 id="_103-板块联动的个股成为今后龙头股的概率较大-除了这点-还需要看什么" tabindex="-1">103. 板块联动的个股成为今后龙头股的概率较大，除了这点，还需要看什么 <a class="header-anchor" href="#_103-板块联动的个股成为今后龙头股的概率较大-除了这点-还需要看什么" aria-label="Permalink to &quot;103. 板块联动的个股成为今后龙头股的概率较大，除了这点，还需要看什么&quot;">​</a></h2><p>联动说明市场资金的关注度高，但是赚钱效应才是激发资金不断进场的最大动力。</p><h2 id="_104-热点板块启动时是追涨龙头还是低吸-如果追龙头-是扫板还是排版" tabindex="-1">104. 热点板块启动时是追涨龙头还是低吸？如果追龙头，是扫板还是排版 <a class="header-anchor" href="#_104-热点板块启动时是追涨龙头还是低吸-如果追龙头-是扫板还是排版" aria-label="Permalink to &quot;104. 热点板块启动时是追涨龙头还是低吸？如果追龙头，是扫板还是排版&quot;">​</a></h2><p>先判定是否主流热点，如是，不必等涨停也可随时先买入，等确认强度后再行加仓。如果不是主流热点，就等待，如果强度够高，就排队龙头，大幅度超过预期，就同时排，但同时仍需注意仓位控制。</p><h2 id="_105-强势板块中-怎么选股" tabindex="-1">105. 强势板块中，怎么选股 <a class="header-anchor" href="#_105-强势板块中-怎么选股" aria-label="Permalink to &quot;105. 强势板块中，怎么选股&quot;">​</a></h2><p>强势阶段，一种直接买强势标的，另一种买低位未启动的。</p><h2 id="_106-小资金如何管理仓位" tabindex="-1">106. 小资金如何管理仓位 <a class="header-anchor" href="#_106-小资金如何管理仓位" aria-label="Permalink to &quot;106. 小资金如何管理仓位&quot;">​</a></h2><p>小资金仓位变动通常较大，在强势阶段，可不必过于在意资金管理，不过如果有意为未来做准备，也可当做大资金来练习分仓操作。</p><h2 id="_107-强势追涨与弱势低吸的逻辑是什么" tabindex="-1">107. 强势追涨与弱势低吸的逻辑是什么 <a class="header-anchor" href="#_107-强势追涨与弱势低吸的逻辑是什么" aria-label="Permalink to &quot;107. 强势追涨与弱势低吸的逻辑是什么&quot;">​</a></h2><p>强势阶段，买股的逻辑是因为赚钱效应下的资金不断进入，那么强的标的被后来资金选中的概率大，所以选强。弱势阶段，买股的逻辑是因为市场亏钱效应的扩散导致恐慌盘的不断宣泄，那么宣泄待尽的，只要少量买盘就可以推动上涨，所以低吸。</p><h2 id="_108-根据技术图形选股-如何进行量化" tabindex="-1">108. 根据技术图形选股，如何进行量化 <a class="header-anchor" href="#_108-根据技术图形选股-如何进行量化" aria-label="Permalink to &quot;108. 根据技术图形选股，如何进行量化&quot;">​</a></h2><p>技术图形相对次要，对于市场情绪的把握才是重点，但是这个没有图表，很难量化，却可以揣摩。</p><h2 id="_109-大的上涨行情时一直持股不动-正确吗" tabindex="-1">109. 大的上涨行情时一直持股不动，正确吗 <a class="header-anchor" href="#_109-大的上涨行情时一直持股不动-正确吗" aria-label="Permalink to &quot;109. 大的上涨行情时一直持股不动，正确吗&quot;">​</a></h2><p>没有对错，看你对市场的认知。就像价值投资者认为，短期的市场是不确定的。但作为短线选手，我认为短期的市场情绪是有规律可循的，长期是无法预料的，于是就演变出不同的操作。</p><p>##% 110. 是否应该做T 至于做T，我会做，但是我不是为了做而做，当中的加仓和减仓，是依据我对市场变化后，受益风险重新衡量后的决策。也许为此错失了很多大牛股，但也规避很多风险。</p><h2 id="_111-短线高手与普通选手的主要区别" tabindex="-1">111. 短线高手与普通选手的主要区别 <a class="header-anchor" href="#_111-短线高手与普通选手的主要区别" aria-label="Permalink to &quot;111. 短线高手与普通选手的主要区别&quot;">​</a></h2><p>在市场热点明确，资金进入C的上涨阶段，大家都很容易赚取盈利。但高手与普通选手的主要区别是在热点退散、资金退散的下跌段的防守能力。短线高手几乎不会出现季度性亏损，盈利从杜绝亏损开始。普通选手的问题是防守，不是进攻。</p><h2 id="_112-弱势中的反弹操作策略与周期分析" tabindex="-1">112. 弱势中的反弹操作策略与周期分析 <a class="header-anchor" href="#_112-弱势中的反弹操作策略与周期分析" aria-label="Permalink to &quot;112. 弱势中的反弹操作策略与周期分析&quot;">​</a></h2><p>（1）职业炒股以来，一直寻找针对股市不同阶段下同时兼顾安全与效率的最佳策略。<br> （2）目前是弱势，就大致说下弱势中的反弹策略。<br> 1&gt; 初期，选择做强势股的回调反抽，或者新热点。<br> 2&gt; 中期，选择做超跌股，重点在时机，一般是连续下跌一段后的再度猛跌时。<br> 3&gt; 末期，选择做符合主流热点有爆发力的强势股。<br> （3）心理分析<br> 1&gt; 下跌初期，市场并不完全认同，仍然期待会有新高，因此对于新热点和强势股的回调的反抽仍然有新高的欲望。<br> 2&gt; 中期，市场已经认同弱势，强势股的反弹往往遭到更多的抛压，而超跌股伴随着崩溃盘得出现，抛压稍显缓解，此时稍有部分买盘便有机会推动超跌股进行一定的反弹。<br> 3&gt; 末期，由于市场对弱势的认同，使得很多资金处在观望状态，随着市场出现部分赚钱效应，这部分外部资金在个别股票上会展现出强大动力。<br> （4）对于目前的格局，初步判定为弱势末期，市场最弱的板块已经有10天以上的相对横盘期，开始出现部分强度较高的强势品种。<br> （5）对于阶段的判断本身也是一个动态的过程，可能会错，但是好的策略，就是在判断错误的时候仍然可以占有一定的应变优势。<br> （6）也许后市还有低点，但是我相信随着盘面出现的一些新的变化，那些在场外观望已久的游资心中那份被隐藏多日的激情又会被重新点燃，此时好的策略就是把筹码放在最有爆发力的个股上。</p><h2 id="_113-弱势中抢反弹-具体如何选股" tabindex="-1">113. 弱势中抢反弹，具体如何选股 <a class="header-anchor" href="#_113-弱势中抢反弹-具体如何选股" aria-label="Permalink to &quot;113. 弱势中抢反弹，具体如何选股&quot;">​</a></h2><p>（1）初期做强势股的回调，选股应该在过去上涨过程中有强大号召力和人气的品种为主，而在进入弱势初期出现较大幅度的回调。<br> （2）中期，找那些跌的最惨的就是，重点在于选时，不过这个对时机的把握相对有较高的难度，没有特别好的机会时，宁愿放弃。<br> （3）末期，符合主流热点的新故事是较好的选择。虽然说的简单点是追涨，但是不同阶段下的把握和后续的应变策略才是重点。</p><h2 id="_114-在弱势中的每个阶段-都有一直走上升趋势的票-是否应该去操作" tabindex="-1">114. 在弱势中的每个阶段，都有一直走上升趋势的票，是否应该去操作 <a class="header-anchor" href="#_114-在弱势中的每个阶段-都有一直走上升趋势的票-是否应该去操作" aria-label="Permalink to &quot;114. 在弱势中的每个阶段，都有一直走上升趋势的票，是否应该去操作&quot;">​</a></h2><p>确实不管在任何阶段都有涨的好的票，但是这也恰恰是让很多纯技术派人士吃面的地方，在主跌段，领跌股加速下跌，此时的强势股的补跌所造成的风险，可能导致一两天内10个点以上的市值回落，对于职业选手而言这是难以容忍的，应该予以回避。</p><h2 id="_115-在弱势中很多短线高手也是始终满仓操作-您如何看待" tabindex="-1">115. 在弱势中很多短线高手也是始终满仓操作，您如何看待 <a class="header-anchor" href="#_115-在弱势中很多短线高手也是始终满仓操作-您如何看待" aria-label="Permalink to &quot;115. 在弱势中很多短线高手也是始终满仓操作，您如何看待&quot;">​</a></h2><p>每个人根据自己的经验和对市场的理解都会有自己的操作，喜欢满仓的，他们用满仓换股的方式，根据市场的变化，将资金始终放在更有利的筹码上。而我大部分时间空仓，因为我根据市场的变化，放弃不确定的和看不懂的，选择赢面较大的机会进行操作。反应在市值曲线上，始终满仓的可能是波段上扬，我的方法则更平滑，不断复利新高，在心理上后者让我更舒服些，因为我是风险极度厌恶型。</p><h2 id="_116-谈谈左侧交易和右侧交易的仓位如何管控" tabindex="-1">116. 谈谈左侧交易和右侧交易的仓位如何管控 <a class="header-anchor" href="#_116-谈谈左侧交易和右侧交易的仓位如何管控" aria-label="Permalink to &quot;116. 谈谈左侧交易和右侧交易的仓位如何管控&quot;">​</a></h2><p>通常情况下右侧的仓位较重，左侧的因为把握难度较大而选择轻仓，具体仓位则根据当时情况下风险收益比所决定。从实际统计中，个人收益的95%以上来自于右侧交易，左侧模式渐渐如同鸡肋，但是为了保持对盘面的敏感度，我仍然会在一些特殊阶段，进行小仓位出击，其实这部分操作的输赢已经不重要，重要的是由此感受到的市场情绪。</p><h2 id="_117-经常看好的票-买入后就出现下跌-止损割肉后又开始上涨-怎么办" tabindex="-1">117. 经常看好的票，买入后就出现下跌，止损割肉后又开始上涨，怎么办 <a class="header-anchor" href="#_117-经常看好的票-买入后就出现下跌-止损割肉后又开始上涨-怎么办" aria-label="Permalink to &quot;117. 经常看好的票，买入后就出现下跌，止损割肉后又开始上涨，怎么办&quot;">​</a></h2><p>（1）其实这个状况，我也一样经常发生的，操作只能根据当时的盘面情况，客观的衡量风险和收益后进行相应的应变。<br> （2）做短线的追求在控制风险的前提下，把握爆发力品种的机会，为了控制风险，有时要错失牛股，为了把握爆发品种，有时要承担风险，但是如果你对风险和收益的判断越客观越准确，时间会展现复利的威力。<br> （3）错失牛股没有关系，偶尔承担风险也没有关系，对于不同状况下风险和收益的衡量才是根本，但是这本身也取决于对你市场的深刻理解。<br> （4）熊市空仓，牛市操作，说起来简单，实际操作时不可能的，从实盘赛的高手也可以看出，他们在熊市多也反复操作，区别在于高手们通常牛市阶段的操作，不断盈利，熊市阶段的操作，则盈亏接近于平衡，实际上在操作的那一刻，很多高手对于大盘的判断也是不确定，是良好的操作策略使然。</p><h2 id="_118-主流题材和各类支流题材应该如何去操作" tabindex="-1">118. 主流题材和各类支流题材应该如何去操作 <a class="header-anchor" href="#_118-主流题材和各类支流题材应该如何去操作" aria-label="Permalink to &quot;118. 主流题材和各类支流题材应该如何去操作&quot;">​</a></h2><p>（1）主流，通常是涨幅大，跨度时间长，操作策略是反复做，第一波赶上的话就做足，没赶上的等回落后还能再做下一波。<br> （2）支流，各支流循序轮动，涨幅各异，时间上契合主流。直至主流完结。策略上，在主流不倒的情况下，按照以主流为中心的逻辑逐步挖掘。<br> （3）次主流，涨幅和时间跨度上小于主流，但是仍然具有一定的可操作性，策略上，以围绕龙头操作为主。<br> （4）非主流，时间短，但是因为技术面或者消息面等因素短期会有一定的爆发力，策略上，快进快出，隔日超短为主，爆发初期可参与，后市不追高。</p><h2 id="_119-追涨和低吸哪个好" tabindex="-1">119. 追涨和低吸哪个好 <a class="header-anchor" href="#_119-追涨和低吸哪个好" aria-label="Permalink to &quot;119. 追涨和低吸哪个好&quot;">​</a></h2><p>追涨也好，低吸也好，问题不在模式，而在何种阶段应用，以及火候。</p><h2 id="_120-弱势就低吸-强势就追高-这个看法对吗" tabindex="-1">120. 弱势就低吸，强势就追高，这个看法对吗 <a class="header-anchor" href="#_120-弱势就低吸-强势就追高-这个看法对吗" aria-label="Permalink to &quot;120. 弱势就低吸，强势就追高，这个看法对吗&quot;">​</a></h2><p>（1）不尽然，弱势和强势也有不同阶段，模式也各异。<br> （2）心理层面的研究在我看来至关重要，我的操作策略基础便来源于此。<br> （3）有人说天下武功唯快不破，我说天下股市唯心法不破。</p><h2 id="_121-如何看待股票中的庄家" tabindex="-1">121. 如何看待股票中的庄家 <a class="header-anchor" href="#_121-如何看待股票中的庄家" aria-label="Permalink to &quot;121. 如何看待股票中的庄家&quot;">​</a></h2><p>我的有些看法可能对你来说是颠覆性的，比如对于庄家和散户，我认为好的股票，主力是散户，而所谓庄家反而是跟风的。</p><h2 id="_122-游资可以引导市场吗" tabindex="-1">122. 游资可以引导市场吗 <a class="header-anchor" href="#_122-游资可以引导市场吗" aria-label="Permalink to &quot;122. 游资可以引导市场吗&quot;">​</a></h2><p>游资绝不是引导市场，而是跟随的更紧一点，也许有人可以引导市场，但是我的模式是坚决反对这么做的。做好一个市场跟随者，我不是一个人在战斗，因为我在市场之内，我做跟随者，不做发动者。</p><h2 id="_123-总是亏钱-那么与市场反向操作-是否可盈利" tabindex="-1">123. 总是亏钱，那么与市场反向操作，是否可盈利 <a class="header-anchor" href="#_123-总是亏钱-那么与市场反向操作-是否可盈利" aria-label="Permalink to &quot;123. 总是亏钱，那么与市场反向操作，是否可盈利&quot;">​</a></h2><p>不刻意反向操作，市场做多，我可能做多，也可能谨慎，单一的理解都可能有失偏颇。</p><h2 id="_124-强势股高位放量后横盘-为什么有些是继续突破-而有些却是大面" tabindex="-1">124. 强势股高位放量后横盘，为什么有些是继续突破，而有些却是大面 <a class="header-anchor" href="#_124-强势股高位放量后横盘-为什么有些是继续突破-而有些却是大面" aria-label="Permalink to &quot;124. 强势股高位放量后横盘，为什么有些是继续突破，而有些却是大面&quot;">​</a></h2><p>（1）早年我研究技术分析时，也始终为此类问题所困惑，纯技术有其局限性，同一张k线图，在不同时期不同背景下，其背后所参与的投资者的心理状态也大不相同。<br> （2）当整个市场经历恐慌盘的释放，市场孕育着一轮反弹的机会，所在强势板块强势个股，再后面抄底资金不断涌入下，会不断走高。而如果市场正处于恐慌初期，则心理状态会大不相同，许多强势个股补跌概率大为增加。<br> （3）如果你能对市场心理有个大致的把握，再来看技术，许多问题就迎刃而解。</p><h2 id="_125-如何把握左侧交易的机会" tabindex="-1">125. 如何把握左侧交易的机会 <a class="header-anchor" href="#_125-如何把握左侧交易的机会" aria-label="Permalink to &quot;125. 如何把握左侧交易的机会&quot;">​</a></h2><p>（1）左侧交易重点是时机的掌握，今日早盘低点市场恐慌情绪得到较好的释放，敢于买入的大多有较好的赢面，短期内市场已经不具备连续大幅杀跌的动力了，可以保有一定仓位灵活应对，争取扩大盈利。<br> （2）作为一个短线交易者，规避弱势大幅回调是重中之重，如果能采取好的策略，事实上这是完全可行的，重点在于对市场情绪的把握，规避崩溃盘带来的伤害，反而转化为自己的利润。</p><h2 id="_126-都说职业一年顶业余十年-是不是应该早点进入职业炒股才能使自己快速提高" tabindex="-1">126. 都说职业一年顶业余十年，是不是应该早点进入职业炒股才能使自己快速提高 <a class="header-anchor" href="#_126-都说职业一年顶业余十年-是不是应该早点进入职业炒股才能使自己快速提高" aria-label="Permalink to &quot;126. 都说职业一年顶业余十年，是不是应该早点进入职业炒股才能使自己快速提高&quot;">​</a></h2><p>（1）职业之前以为自己懂了？现在想想其实不懂。之前的所赚大部分拜07年大牛市所赐，08年进入职业，从90多万，最低被打到40w不到，面对房供、车子油钱、小孩奶粉钱等所带来的迷茫和压力只有经历过的人能懂。<br> （2）迷茫困惑的之后支持我的是信念，职业炒手、Asking这些人可以从股市赚上千万上亿，是什么让他们获得如此的成就，股市既然是一个群体博弈，其背后参与者的行为模式一定有其规律，通过对心理模式的不断深入研究，终于发现是可行的。<br> （3）职业一年确实顶过十年，至少我是这样的，08年的一轮熊市若不是职业，恐怕受教也不会这么深刻，之后顿悟，此后3478至今，所有的大跌全部规避，知道梦想就在眼前了。<br> （4）只是在岸上是很难学会游泳的，但是下水了难免也要被呛到，至于是否职业，这本身也是一次赌博，每个人的情况不一样。</p><h2 id="_127-您是不是只求操作的成功率-对单次盈利的点位没有过高的要求" tabindex="-1">127. 您是不是只求操作的成功率，对单次盈利的点位没有过高的要求 <a class="header-anchor" href="#_127-您是不是只求操作的成功率-对单次盈利的点位没有过高的要求" aria-label="Permalink to &quot;127. 您是不是只求操作的成功率，对单次盈利的点位没有过高的要求&quot;">​</a></h2><p>收益不是不要求高，是要求高，关键战役的把握很重要，力求利润最大化，虽然很多单子实际结果是赚一两个点，但是买入的那一刻绝不是只冲着一两个点去的。</p><h2 id="_128-做超跌反弹要是还没跌透-怎么办" tabindex="-1">128. 做超跌反弹要是还没跌透，怎么办 <a class="header-anchor" href="#_128-做超跌反弹要是还没跌透-怎么办" aria-label="Permalink to &quot;128. 做超跌反弹要是还没跌透，怎么办&quot;">​</a></h2><p>我买的时候当然想过这个问题，我的回答是，如果今天再跌，我再买。如果你要再问，如果又跌怎么办，我只能说我的操作是按照大概率赢面的角度出发，如果市场一定要连续下跌让我亏一笔钱也无妨，等反抽卖出就是了。只要我的出击是符合大概率赢面，并不影响整体的收益。</p><h2 id="_129-早盘最先涨停的票-根据什么来判断其明后天能继续走升势" tabindex="-1">129. 早盘最先涨停的票，根据什么来判断其明后天能继续走升势 <a class="header-anchor" href="#_129-早盘最先涨停的票-根据什么来判断其明后天能继续走升势" aria-label="Permalink to &quot;129. 早盘最先涨停的票，根据什么来判断其明后天能继续走升势&quot;">​</a></h2><p>分析市场情绪可以参考类似柏拉爱空一样的对于异动个股的及其第二天走势分析统计，个人还会对各个阶段的一些板块变化也进行类似分析，尽可能让自己的观点保持客观。（现在可直接参考昨日涨停股今日表现这个指标）</p><h2 id="_130-有时买到了大牛股-但经常在上升过程中被洗出了-怎么办" tabindex="-1">130. 有时买到了大牛股，但经常在上升过程中被洗出了，怎么办 <a class="header-anchor" href="#_130-有时买到了大牛股-但经常在上升过程中被洗出了-怎么办" aria-label="Permalink to &quot;130. 有时买到了大牛股，但经常在上升过程中被洗出了，怎么办&quot;">​</a></h2><p>赚自己该赚的部分，我也经常被洗，但也因此规避了很多回调的风险，然后在此基础上偶尔把握几次大赚的机会。</p><h2 id="_131-您说的预判埋伏-是指热点出现之前的提前埋伏还是上涨过程中的低位埋伏" tabindex="-1">131. 您说的预判埋伏，是指热点出现之前的提前埋伏还是上涨过程中的低位埋伏 <a class="header-anchor" href="#_131-您说的预判埋伏-是指热点出现之前的提前埋伏还是上涨过程中的低位埋伏" aria-label="Permalink to &quot;131. 您说的预判埋伏，是指热点出现之前的提前埋伏还是上涨过程中的低位埋伏&quot;">​</a></h2><p>如果一个市场的热点还没有出现前就埋伏，几乎是不可能的，大多还是对于现有热点的回档，或者是有待挖掘品的埋伏。</p><h2 id="_132-处在高位震荡的股票-应该持有还是卖出" tabindex="-1">132. 处在高位震荡的股票，应该持有还是卖出 <a class="header-anchor" href="#_132-处在高位震荡的股票-应该持有还是卖出" aria-label="Permalink to &quot;132. 处在高位震荡的股票，应该持有还是卖出&quot;">​</a></h2><p>更多的还是通过市场情绪的判断，有时候我会问自己手上的股票觉得明天涨停的可能大不大，跌停的可能大不大，如果觉得涨停完全没可能，而又有跌停的可能，那就尽快回避，如果涨停有可能，而跌停完全没可能，那就拿一拿。</p><h2 id="_133-追涨龙头后遇到高位调整-是应先卖出然后再择机买入-还是持股不动或者做t" tabindex="-1">133. 追涨龙头后遇到高位调整，是应先卖出然后再择机买入，还是持股不动或者做T <a class="header-anchor" href="#_133-追涨龙头后遇到高位调整-是应先卖出然后再择机买入-还是持股不动或者做t" aria-label="Permalink to &quot;133. 追涨龙头后遇到高位调整，是应先卖出然后再择机买入，还是持股不动或者做T&quot;">​</a></h2><p>（1）我的方法是从个股到板块到大盘整体，感受场内的筹码是等着反弹要卖出，还是场外的资金等着进一步下跌后买入，两种情绪的对比，哪种更强烈，占得比例更高。<br> （2）通常的结果是筹码都等着反弹卖，就没有反弹，或者资金都急不可耐的想等回调进场，那么就难回调，如果能体会到这种情绪，自然知道怎么做才会让自己更主动。</p><h2 id="_134-敢于大盘低位空仓-敢于大盘高位满仓-是顺应市场趋势-可以这样理解吗" tabindex="-1">134. 敢于大盘低位空仓，敢于大盘高位满仓，是顺应市场趋势，可以这样理解吗 <a class="header-anchor" href="#_134-敢于大盘低位空仓-敢于大盘高位满仓-是顺应市场趋势-可以这样理解吗" aria-label="Permalink to &quot;134. 敢于大盘低位空仓，敢于大盘高位满仓，是顺应市场趋势，可以这样理解吗&quot;">​</a></h2><p>（1）大多数人对于高低的判断往往依据历史，事实上我们的股票历史只有短短的二十多年，这种依据是缺乏科学统计的。<br> （2）比如现在感觉大盘是低位，有人就会觉得已经这么低了还能跌到哪里去，恰恰这样的想法是危险之极的。<br> （3）股票操作是门科学，我们就要以科学的态度来面对。</p><h2 id="_135-高手买入龙头-超级高手卖出龙头" tabindex="-1">135. 高手买入龙头，超级高手卖出龙头 <a class="header-anchor" href="#_135-高手买入龙头-超级高手卖出龙头" aria-label="Permalink to &quot;135. 高手买入龙头，超级高手卖出龙头&quot;">​</a></h2><p>龙头是指已经积聚人气，已有一段上涨且仍在上涨途中的股票，此时的高手会迅速介入，吃后半段的涨势，而超级高手因为在揣摩了市场的情绪和动向后，已经打了提前仓位介入，当气势形成，成为公众的龙头之后，风险也在悄然而至，所以超级高手是越涨越抛，直至清仓。</p><h2 id="_136-如何控制人性的贪婪与恐惧" tabindex="-1">136. 如何控制人性的贪婪与恐惧 <a class="header-anchor" href="#_136-如何控制人性的贪婪与恐惧" aria-label="Permalink to &quot;136. 如何控制人性的贪婪与恐惧&quot;">​</a></h2><p>（1）人贪婪是因为他赚钱了，一个充斥赚钱效应的市场通常机会多过风险，此期间力求更大限度博取利润。<br> （2）人恐慌是因为他亏钱了，一个充斥亏钱效应的市场通常风险多过机会，此期间力求更大限度回避风险。<br> （3）市场很多人讨论的是如何克服贪婪和恐慌，虽然不错，但是着眼点在仅在自身，难免局限。<br> （4）高手进出，买卖的一刻力求淡定，借助市场的贪婪和恐慌反过来指导决策，着眼点在整个市场，境界自然高了一层。</p><h2 id="_137-别人贪婪时我更贪婪-别人恐慌时我更恐慌" tabindex="-1">137. 别人贪婪时我更贪婪，别人恐慌时我更恐慌 <a class="header-anchor" href="#_137-别人贪婪时我更贪婪-别人恐慌时我更恐慌" aria-label="Permalink to &quot;137. 别人贪婪时我更贪婪，别人恐慌时我更恐慌&quot;">​</a></h2><p>别人贪婪时我更贪婪，是指敢于大盘高位满仓，让利润最大化；别人恐慌时我更恐慌，是指敢于大盘低位空仓，将风险降到最低。</p><h2 id="_138-心中无顶底-操作自随心-永不止损-永不止盈" tabindex="-1">138. 心中无顶底，操作自随心，永不止损，永不止盈 <a class="header-anchor" href="#_138-心中无顶底-操作自随心-永不止损-永不止盈" aria-label="Permalink to &quot;138. 心中无顶底，操作自随心，永不止损，永不止盈&quot;">​</a></h2><p>心中无顶底，操作自随心，自然就是要永不止损，永不止盈，止损、止盈是相对于买入成本而言的，所以买入之后，心中要无成本的概念，操作唯有根据大势、盘面，顺势而为，操作自随心的心，并不是随心所欲的心，这颗心是经过多年磨练，已经无欲无惧，此心顺应趋势，操作随心而至。</p><h2 id="_139-得散户心者-得天下-人气所向-牛股所在" tabindex="-1">139. 得散户心者，得天下，人气所向，牛股所在 <a class="header-anchor" href="#_139-得散户心者-得天下-人气所向-牛股所在" aria-label="Permalink to &quot;139. 得散户心者，得天下，人气所向，牛股所在&quot;">​</a></h2><p>得散户心者得天下，是在传媒、政策等因素的引导下，制造题材，积聚人气，且达成共识的领域里最容易出现牛股。</p><h2 id="_140-对市场情绪的揣摩主要观察哪些方面" tabindex="-1">140. 对市场情绪的揣摩主要观察哪些方面 <a class="header-anchor" href="#_140-对市场情绪的揣摩主要观察哪些方面" aria-label="Permalink to &quot;140. 对市场情绪的揣摩主要观察哪些方面&quot;">​</a></h2><p>（1）柏拉爱空每天的收评中都有个统计指标，是以前一天涨幅前20名的个股第二天的表现为基准，类似这样的统计指标就是市场情绪的一部分。<br> （2）本人对于类似的统计，另外加入领跌品种，包括各个周期阶段的领涨领跌板块。<br> （3）以柏拉爱空的指标而言反应的是这个市场上喜欢追涨的一批人的盈亏状况，通常而言喜欢追涨的人能赚钱，他们会倾向于再次重复追涨的动作，当此动作一再重复并多次赚钱后，便会影响到周围人群，而自身甚至产生埋怨出击仓位太少的心态，以至于逐步将行情推向高潮，直到这种赚钱效应告一段落；而如果追涨的人开始逐步亏钱，他们便会出现自我惩罚心理，操作上则趋于谨慎，反应在盘面上则是活跃度逐步下降。<br> （4）同样，这个市场上也存在一批喜欢逢下跌抄底的人，如果抄底的人能赚，则他们仍会继续抄底，反应在盘面上就是大盘难以大幅下跌，而一旦抄底的人开始亏钱，他们同样也会出现自我惩罚心理，操作上则减少抄底的动作，而一旦抄底的人开始减少，部分股票稍有卖压便产生无抵抗式下跌，这即是逐步引发崩溃的前兆，直到卖出者无以为继。</p><h2 id="_141-什么是套利性机会" tabindex="-1">141. 什么是套利性机会 <a class="header-anchor" href="#_141-什么是套利性机会" aria-label="Permalink to &quot;141. 什么是套利性机会&quot;">​</a></h2><p>板块向上，大盘向下的时候，实际上也是赚钱效应和亏钱效应相对共存的期间，但是之后市场会逐步趋向于一致，部分具有同类题材的个股走势可能并没有跟随板块向上，反而跟随大盘下跌，他们便产生了一定的套利效应。在板块一再活跃的背景下，它们可能被市场挖掘出来。但它们的上涨的因素只是低价填权。这就是我说的套利性机会。</p><h2 id="_142-每次操作主流板块时-都只敢做跟风-不敢追涨龙头-如何克服这个心理" tabindex="-1">142. 每次操作主流板块时，都只敢做跟风，不敢追涨龙头，如何克服这个心理 <a class="header-anchor" href="#_142-每次操作主流板块时-都只敢做跟风-不敢追涨龙头-如何克服这个心理" aria-label="Permalink to &quot;142. 每次操作主流板块时，都只敢做跟风，不敢追涨龙头，如何克服这个心理&quot;">​</a></h2><p>（1）或许你需要解决的不是有胆做龙头的问题，而应领会龙头和跟风品种间的套利关系。<br> （2）有时买龙头不是因为胆子大，而是根据板块整体动能，龙头有相应溢价，而股价尚未反应溢价时介入；有时买跟风，不是因为胆子小，是因为龙头赚钱效应十足，而部分跟风品种尚处低位，有随时受龙头激发而具备向上潜力。</p><h2 id="_143-心法和市场之间的关系" tabindex="-1">143. 心法和市场之间的关系 <a class="header-anchor" href="#_143-心法和市场之间的关系" aria-label="Permalink to &quot;143. 心法和市场之间的关系&quot;">​</a></h2><p>（1）掌握市场之心，胜利接踵而至；心被市场掌握，失败连绵不绝。<br> （2）买卖那一刻的淡定自如，亦是自身境界的提升。</p><h2 id="_144-如何判断大盘要崩溃-特别是热点还有持续性的时候" tabindex="-1">144. 如何判断大盘要崩溃，特别是热点还有持续性的时候 <a class="header-anchor" href="#_144-如何判断大盘要崩溃-特别是热点还有持续性的时候" aria-label="Permalink to &quot;144. 如何判断大盘要崩溃，特别是热点还有持续性的时候&quot;">​</a></h2><p>（1）领跌品种中，部分是近期强势股，这会在一定程度上打击后市追涨的热情，同时也说明赚钱效应有一定程度降低。<br> （2）更为重要的是让一部分喜欢抄底的资金陷入被套局面，而抄底的人也亏钱的话，继续抄底的就会减少，这种状况就可能引发崩溃。<br> （3）这种盘面现象表示后市有一定崩盘的概率，不过这本身也是一个动态的判断过程，只是当下先空仓或低仓位回避这种概率，会使自己操作上更为主动。</p><h2 id="_145-如何控制让自己不发生大的回撤" tabindex="-1">145. 如何控制让自己不发生大的回撤 <a class="header-anchor" href="#_145-如何控制让自己不发生大的回撤" aria-label="Permalink to &quot;145. 如何控制让自己不发生大的回撤&quot;">​</a></h2><p>（1）控制回撤，最重要的就是回避系统性崩溃风险，事实上绝大部分崩溃都有前兆，从赚钱和亏钱效应的演变过程可以进行推断，不过为此可能也会放弃很多机会。<br> （2）看看天气，如果觉得要下雨了，就早点回家，不要贪玩，天气好了再出来，说简单点就这样。</p><h2 id="_146-什么样的股票才是最好的股票" tabindex="-1">146. 什么样的股票才是最好的股票 <a class="header-anchor" href="#_146-什么样的股票才是最好的股票" aria-label="Permalink to &quot;146. 什么样的股票才是最好的股票&quot;">​</a></h2><p>（1）每个人心中有各自不同的第一股，真正的第一股始终是市场决定的，而市场本身又也是不断动态变化的。<br> （2）我们操作的本身就是追求在这个动态变化的过程中使自己的筹码尽量在相对有利的方向上。</p>',304)]))}const c=e(l,[["render",i]]);export{_ as __pageData,c as default};
